const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\r?\n/);
const [N, M] = data[0].split(' ').map(Number);
const grid = [];
for (let i = 0; i < N; i++) {
  grid.push(data[i + 1].split(''));
}

const queue = [];
for (let i = 0; i < N; i++) {
  for (let j = 0; j < M; j++) {
    if (grid[i][j] === 'o') {
      queue.push(i * M + j);
    }
  }
}

let head = 0;
while (head < queue.length) {
  const idx = queue[head++];
  const r = Math.floor(idx / M);
  const c = idx % M;

  // Water falls straight down
  if (r + 1 < N && grid[r + 1][c] === '.') {
    grid[r + 1][c] = 'o';
    queue.push((r + 1) * M + c);
  }

  // Water spreads horizontally if there is a shelf directly below
  if (r + 1 < N && grid[r + 1][c] === '#') {
    if (c - 1 >= 0 && grid[r][c - 1] === '.') {
      grid[r][c - 1] = 'o';
      queue.push(r * M + (c - 1));
    }
    if (c + 1 < M && grid[r][c + 1] === '.') {
      grid[r][c + 1] = 'o';
      queue.push(r * M + (c + 1));
    }
  }
}

console.log(grid.map(row => row.join('')).join('\n'));
